// MinimockListBucketsInspect logs each unmet expectation
func (m *BucketServiceMock) MinimockListBucketsInspect() {
	for _, e := range m.ListBucketsMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to BucketServiceMock.ListBuckets at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterListBucketsCounter := mm_atomic.LoadUint64(&m.afterListBucketsCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.ListBucketsMock.defaultExpectation != nil && afterListBucketsCounter < 1 {
		if m.ListBucketsMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to BucketServiceMock.ListBuckets at\n%s", m.ListBucketsMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to BucketServiceMock.ListBuckets at\n%s with params: %#v", m.ListBucketsMock.defaultExpectation.expectationOrigins.origin, *m.ListBucketsMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcListBuckets != nil && afterListBucketsCounter < 1 {
		m.t.Errorf("Expected call to BucketServiceMock.ListBuckets at\n%s", m.funcListBucketsOrigin)
	}

	if !m.ListBucketsMock.invocationsDone() && afterListBucketsCounter > 0 {
		m.t.Errorf("Expected %d calls to BucketServiceMock.ListBuckets at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.ListBucketsMock.expectedInvocations), m.ListBucketsMock.expectedInvocationsOrigin, afterListBucketsCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *BucketServiceMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockCreateBucketInspect()

			m.MinimockDeleteBucketInspect()

			m.MinimockGetBucketInspect()

			m.MinimockHeadBucketInspect()

			m.MinimockListBucketsInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *BucketServiceMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *BucketServiceMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockCreateBucketDone() &&
		m.MinimockDeleteBucketDone() &&
		m.MinimockGetBucketDone() &&
		m.MinimockHeadBucketDone() &&
		m.MinimockListBucketsDone()
}
